def md5(yol):
    return hashlib.md5(open(yol, "rb").read()).hexdigest()


def git(*a):
    return subprocess.run(["git"] + list(a), capture_output=True, text=True)


if not os.path.isdir("app/engine") or not os.path.isdir(".git"):
    sys.exit("HATA: osmanlica kod klasorunde degilsin (app/engine ve .git yok)")
patch = base64.b64decode("".join(VERI))
if hashlib.md5(patch).hexdigest() != PATCH_MD5:
    sys.exit("HATA: yama icerigi bozuk (md5 tutmuyor); dosyayi yeniden indir")
with tempfile.NamedTemporaryFile("wb", suffix=".patch", delete=False) as f:
    f.write(patch)
    yol = f.name
if all(os.path.exists(k) and md5(k) == v for k, v in BEKLENEN.items()):
    print("ATLANDI: Tur L zaten uygulanmis")
    sys.exit(0)
if git("apply", "--check", yol).returncode != 0:
    print(git("apply", "--check", yol).stderr)
    sys.exit("HATA: yama bu koda uygulanamiyor (Tur K / 1d31918 bekleniyor; git log -1 ve git status --short ile bak)")
r = git("apply", yol)
if r.returncode != 0:
    sys.exit("HATA: " + r.stderr)
for k, v in BEKLENEN.items():
    print(("TAMAM " if md5(k) == v else "HATA md5 farkli ") + k)
print("Tur L uygulandi. Degisen dosyalar: git status --short")
